import random
import string


def make_complex_nested_random_dict(max_width: int, max_depth: int) -> dict:
	"""
	Create a random dict that is nested up to `max_depth` levels deep, where
	each dict and list contains up to `max_width` items. The generated values
	cover all json types, and the generated strings contain characters that
	need to be escaped, which makes the result suitable for integrity tests.
	"""

	def random_string(choices, md):
		length = random.randint(0, max_width)
		letters = string.ascii_letters + "".join(["\\", " ", "🚀", '"'])
		return "".join(random.choices(letters, k=length))

	def random_int(choices, md):
		return random.randint(-1000, 1000)

	def random_float(choices, md):
		return random.uniform(-1000, 1000)

	def random_bool(choices, md):
		return random.choice([True, False])

	def random_none(choices, md):
		return None

	def random_list(choices, md):
		if md == 0:
			return []
		res = []
		for _ in range(random.randint(0, max_width)):
			res += [random.choice(choices)(choices, md - 1)]
		return res

	def random_dict(choices, md):
		if md == 0:
			return {}
		res = {}
		for _ in range(random.randint(0, max_width)):
			k = random_string(choices, md)
			res[k] = random.choice(choices)(choices, md - 1)
		return res

	return random_dict(
		[random_string, random_int, random_float, random_bool, random_none, random_list, random_dict],
		max_depth,
	)

