import pytest
from path_dict import pd

import dictdatabase as DDB

users = {
	"u1": {"name": "Alice", "age": 25},
	"u2": {"name": "Bob", "age": 17},
}


def test_session_file_full(use_compression, use_orjson, indent):
	DDB.at("users").create(users)
	with DDB.at("users").session() as (session, db):
		db["u1"]["age"] = 26
		db["u3"] = {"name": "Charlie", "age": 35}
		session.write()
	assert DDB.at("users").read() == {
		"u1": {"name": "Alice", "age": 26},
		"u2": {"name": "Bob", "age": 17},
		"u3": {"name": "Charlie", "age": 35},
	}


def test_session_file_key(use_compression, use_orjson, indent):
	DDB.at("users").create(users)
	with DDB.at("users", key="u2").session() as (session, user):
		user["age"] += 1
		session.write()
	assert DDB.at("users").read() == {
		"u1": {"name": "Alice", "age": 25},
		"u2": {"name": "Bob", "age": 18},
	}


def test_session_file_key_nonexistent(use_compression, use_orjson, indent):
	DDB.at("users").create(users)
	with pytest.raises(KeyError):
		with DDB.at("users", key="u9").session() as (session, user):
			session.write()


def test_session_file_where(use_compression, use_orjson, indent):
	DDB.at("users").create(users)
	with DDB.at("users", where=lambda k, v: v["age"] < 18).session() as (session, minors):
		for user in minors.values():
			user["status"] = "minor"
		session.write()
	db = DDB.at("users").read()
	assert db["u2"]["status"] == "minor"
	assert "status" not in db["u1"]


def test_session_dir_full(use_compression, use_orjson, indent):
	for i in range(3):
		DDB.at("purchases", f"p{i}").create({"amount": i})

	with DDB.at("purchases/*").session() as (session, purchases):
		assert set(purchases.keys()) == {"p0", "p1", "p2"}
		for purchase in purchases.values():
			purchase["processed"] = True
		session.write()

	assert DDB.at("purchases/*").read() == {f"p{i}": {"amount": i, "processed": True} for i in range(3)}


def test_session_dir_where(use_compression, use_orjson, indent):
	for i in range(4):
		DDB.at("purchases", f"p{i}").create({"amount": i})

	with DDB.at("purchases/*", where=lambda k, v: v["amount"] >= 2).session() as (session, selected):
		assert set(selected.keys()) == {"p2", "p3"}
		for purchase in selected.values():
			purchase["amount"] *= 10
		session.write()

	assert DDB.at("purchases/*").read() == {
		"p0": {"amount": 0},
		"p1": {"amount": 1},
		"p2": {"amount": 20},
		"p3": {"amount": 30},
	}


def test_session_as_type(use_compression, use_orjson, indent):
	DDB.at("counter").create({})
	with DDB.at("counter").session(as_type=pd) as (session, d):
		d["deeply", "nested", "counter"] = lambda x: (x or 0) + 1
		session.write()
	assert DDB.at("counter").read() == {"deeply": {"nested": {"counter": 1}}}


def test_session_of_nonexistent_file(use_compression, use_orjson, indent):
	with pytest.raises(FileNotFoundError):
		with DDB.at("nonexistent").session() as (session, d):
			session.write()


def test_no_write_without_session(use_compression, use_orjson, indent):
	DDB.at("users").create(users)
	session = DDB.at("users").session()
	with pytest.raises(PermissionError):
		session.write()


def test_exception_in_session_does_not_write(use_compression, use_orjson, indent):
	DDB.at("users").create(users)
	with pytest.raises(RuntimeError):
		with DDB.at("users").session() as (session, db):
			db["u1"]["age"] = 99
			raise RuntimeError("Something went wrong")
	assert DDB.at("users").read() == users
	# The lock was released, so the file is accessible again
	with DDB.at("users").session() as (session, db):
		session.write()


def test_nested_session_on_same_file_raises(use_compression, use_orjson, indent):
	DDB.at("users").create(users)
	with pytest.raises(RuntimeError):
		with DDB.at("users").session() as (session, db):
			with DDB.at("users").session() as (session2, db2):
				pass

