import struct, zlib

W = H = 256

def px(x, y):
	# Dark background with a lighter rounded "document" shape and two "pages"
	cx, cy = x - W / 2, y - H / 2
	bg = (28, 32, 38)
	# Rounded square card
	r = 92
	inside = (abs(cx) < r and abs(cy) < r) and (min(r - abs(cx), r - abs(cy)) > 0)
	corner = (abs(cx) > r - 28 and abs(cy) > r - 28)
	if corner and ((abs(cx) - (r - 28)) ** 2 + (abs(cy) - (r - 28)) ** 2) > 28 ** 2:
		inside = False
	if not inside:
		return bg
	# Curly brace like stripes: three horizontal bars of decreasing width
	for i, (top, width) in enumerate(((-52, 96), (-8, 68), (36, 40))):
		if top <= cy <= top + 24 and -width <= cx <= width:
			return (80 + i * 40, 190 - i * 20, 120 + i * 45)
	return (44, 50, 58)

raw = bytearray()
for y in range(H):
	raw.append(0)  # filter type 0
	for x in range(W):
		raw.extend(px(x, y))

def chunk(tag, data):
	return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)

png = b"\x89PNG\r\n\x1a\n"
png += chunk(b"IHDR", struct.pack(">IIBBBBB", W, H, 8, 2, 0, 0, 0))
png += chunk(b"IDAT", zlib.compress(bytes(raw), 9))
png += chunk(b"IEND", b"")

with open("/workspace/assets/logo.png", "wb") as f:
	f.write(png)
print("wrote", len(png), "bytes")
